const state={cards:[],track:'all',query:''};
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtDate=v=>{if(!v)return '日期未知';const d=new Date(v);return Number.isNaN(d.valueOf())?v:new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'short',day:'numeric'}).format(d)};
const labelMap={paradigm_novelty:'范式新颖性',musculoskeletal_gap:'肌骨空白度',clinical_significance:'临床意义',data_feasibility:'数据可行性',mechanistic_depth:'机制深度',competition_urgency:'竞争紧迫度'};

function cardNode(c){
  const node=$('#cardTemplate').content.firstElementChild.cloneNode(true);node.classList.add(`track-${c.track}`);
  $('.tags',node).innerHTML=`<span class="tag track">Track ${esc(c.track)}</span><span class="tag">${esc(c.novelty_status)}</span>${c.publication_status==='preprint'?'<span class="tag preprint">PREPRINT</span>':''}`;
  $('.score strong',node).textContent=c.score_total;$('h2',node).textContent=c.title;
  $('.citation',node).textContent=[c.journal,fmtDate(c.published_date),c.doi?`DOI ${c.doi}`:'',c.pmid?`PMID ${c.pmid}`:''].filter(Boolean).join(' · ');
  $('.summary',node).innerHTML=(c.summary_zh||[]).map(x=>`<p>${esc(x)}</p>`).join('');$('.signal-line p',node).textContent=c.new_paradigm;
  const competition=(c.competition||[]).map(x=>`<li><a class="source-link" href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)}</a> · ${esc(x.journal||'')} ${esc(x.date||'')}</li>`).join('')||'<li>当前自动检索未返回直接结果；不等于证明不存在相关研究。</li>';
  const bars=Object.entries(c.score_components||{}).map(([k,v])=>`<div class="score-row" title="${esc((c.score_reasons||{})[k]||'')}"><span>${esc(labelMap[k]||k)}</span><div class="bar"><i style="width:${Number(v)}%"></i></div><b>${Number(v)}</b></div>`).join('');
  $('.details',node).innerHTML=`<div class="detail-grid"><div><h3>为什么现在才做得出来</h3><p>${esc(c.why_now)}</p></div><div><h3>与骨 / 肌的联系</h3><p>${esc(c.musculoskeletal_link)}</p></div><div><h3>尚未解决的问题</h3><ul>${(c.unresolved_questions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>可迁移到骨科的问题</h3><ul>${(c.transfer_questions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>所需数据</h3><p>${(c.data_needs||[]).map(esc).join(' · ')}</p></div><div><h3>原始证据</h3><a class="source-link" href="${esc(c.url)}" target="_blank" rel="noopener">打开原文 ↗</a></div><div class="wide"><h3>Opportunity Score 分项</h3><div class="score-bars">${bars}</div></div><div class="wide"><h3>自动构造的二次检索词</h3>${(c.secondary_queries||[]).map(q=>`<div class="query">${esc(q)}</div>`).join('')}</div><div class="wide"><h3>直接竞争研究（当前检索）</h3><ul>${competition}</ul></div></div>`;
  const button=$('.expand',node);button.addEventListener('click',()=>{const details=$('.details',node);const open=details.hidden;details.hidden=!open;button.setAttribute('aria-expanded',String(open));button.innerHTML=`${open?'收起':'展开'}证据与迁移路径 <span>${open?'−':'＋'}</span>`});return node;
}
function fillCards(target,cards){const root=$(target);root.replaceChildren();if(!cards.length){root.innerHTML='<div class="empty-state">当前筛选下没有高优先级机会。继续保留检索历史，等待下一次扫描。</div>';return}cards.forEach(c=>root.append(cardNode(c)))}
function filtered(){return state.cards.filter(c=>(state.track==='all'||c.track===state.track)&&(!state.query||`${c.title} ${c.journal} ${c.new_paradigm}`.toLowerCase().includes(state.query)))}
function renderMain(){fillCards('#todayCards',filtered().filter(c=>c.score_total>=68).slice(0,8));fillCards('#allCards',state.cards);fillCards('#preprintCards',state.cards.filter(c=>c.publication_status==='preprint'));fillCards('#methodCards',state.cards.filter(c=>c.track==='B'))}
function renderMetrics(stats){const items=[['高价值机会',stats.high_value,'accent'],['Track A',stats.track_a,''],['Track B',stats.track_b,''],['预印本信号',stats.preprints,'']];$('#metrics').innerHTML=items.map(([l,v,k])=>`<div class="metric ${k}"><strong>${Number(v||0).toString().padStart(2,'0')}</strong><span>${l}</span></div>`).join('')}
function renderTrends(){const terms=['spatial','single-cell','foundation model','longitudinal','proteomics','metabolomics','multimodal','perturbation','atlas'];const counts=terms.map(term=>({term,count:state.cards.filter(c=>`${c.title} ${c.new_paradigm}`.toLowerCase().includes(term)).length})).sort((a,b)=>b.count-a.count);const max=Math.max(1,...counts.map(x=>x.count));$('#trendGrid').innerHTML=counts.map((x,i)=>`<article class="trend-item"><p class="eyebrow">${String(i+1).padStart(2,'0')} · SIGNAL</p><strong>${esc(x.term)}</strong><div class="spark"><i style="width:${x.count/max*100}%"></i></div><small>${x.count} 篇机会卡命中</small></article>`).join('')}
function renderCompetition(){const cards=state.cards.filter(c=>(c.competition||[]).length);$('#competitionList').innerHTML=cards.length?cards.map(c=>`<article class="alert-item"><div class="alert-score">${c.score_total}</div><div><h3>${esc(c.title)}</h3><p>${c.competition.length} 条潜在竞争记录 · ${esc(c.novelty_status)}</p></div><a href="${esc(c.url)}" target="_blank" rel="noopener">查看原文 ↗</a></article>`).join(''):'<div class="empty-state">当前没有需要升级处理的竞争预警。</div>'}
function showView(name){$$('.view').forEach(x=>x.classList.toggle('active',x.dataset.view===name));$$('.side-nav a').forEach(x=>x.classList.toggle('active',x.dataset.view===name));window.scrollTo({top:0,behavior:'smooth'})}
function ideas(){try{return JSON.parse(localStorage.getItem('msk-radar-ideas')||'[]')}catch{return[]}}
function renderIdeas(){const root=$('#ideaList'),items=ideas();root.innerHTML=items.length?items.map((x,i)=>`<article class="idea"><div><h3>${esc(x.title)}</h3><p>${esc(x.note||'暂无备注')}</p></div><button data-index="${i}" aria-label="删除 ${esc(x.title)}">删除</button></article>`).join(''):'<div class="empty-state">还没有保存研究想法。看到机会卡后，把最想验证的问题记在这里。</div>';$$('button[data-index]',root).forEach(b=>b.onclick=()=>{const next=ideas();next.splice(Number(b.dataset.index),1);localStorage.setItem('msk-radar-ideas',JSON.stringify(next));renderIdeas()})}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),2200)}
async function init(){
  try{const res=await fetch('data.json',{cache:'no-store'});if(!res.ok)throw new Error(`HTTP ${res.status}`);const data=await res.json();state.cards=data.cards||[];renderMetrics(data.stats||{});renderMain();renderTrends();renderCompetition();$('#updatedAt').textContent=`最近扫描 ${fmtDate(data.generated_at)}`;$('#todayDate').textContent=fmtDate(data.generated_at)}catch(err){$('#todayCards').innerHTML=`<div class="empty-state">数据暂时不可用：${esc(err.message)}。请先运行一次雷达任务。</div>`;$('#updatedAt').textContent='数据读取失败'}
  renderIdeas();
}
$$('.side-nav a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();history.replaceState(null,'',a.hash);showView(a.dataset.view)}));
$$('[data-track]').forEach(b=>b.addEventListener('click',()=>{$$('[data-track]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.track=b.dataset.track;renderMain()}));
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();renderMain()});
$('#ideaForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),items=ideas();items.unshift({title:fd.get('title'),note:fd.get('note'),createdAt:new Date().toISOString()});localStorage.setItem('msk-radar-ideas',JSON.stringify(items));e.currentTarget.reset();renderIdeas();toast('研究想法已保存到本机')});
showView(location.hash.slice(1)||'today');init();
